head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > E > onchange]<br/>컴포넌트에서 아이템들의 선택이 변경되면 발생합니다.",
    "validation" : [        
        "컴포넌트에서 아이템들의 선택이 변경되면 발생합니다.",
        "아이템들의 선택이 변경되지 않은 경우 onchange 이벤트는 발생하지 않습니다.",
        "info 파라미터로 선택이 변경된 아이템들의 정보가 객체로 전달됩니다.",
        "info.oldValue 속성값으로 변경 전에 선택되어 있던 아이템들의 Value 값을 separator 속성값으로 구분한 값을 갖습니다.",
        "info.oldValue 속성값으로 선택되어 있던 아이템이 한 개인 경우 구분자 없이 해당 아이템의 Value 값만 갖습니다.",
        "info.oldValue 속성값으로 기존에 선택된 아이템이 없는 경우 ''(Empty String)값을 갖습니다.",
        "info.newValue 속성값으로 변경 후에 선택된 아이템들의 Value 값을 separator 속성값으로 구분한 값을 갖습니다.",
        "info.newValue 속성값으로 선택된 아이템이 한 개인 경우 구분자 없이 해당 아이템의 Value 값만 갖습니다.",
        "info.newValue 속성값으로 모든 아이템이 선택되지 않은 경우 ''(Empty String)값을 갖습니다.",                
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onchange"]);

    // comp 생성
    $c.gcm.createBasicCheckComboBox('', eList);
}



scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
}
